export default function FunctionExpression(objectExpression, hasSelf) {
    let params = [];
    if(hasSelf) {
        params = [
            {
                "type": "Identifier",
                "name": "self"
            }
        ];
    }
    return {
        "type": "FunctionExpression",
        "id": null,
        "params": params,
        "defaults": [],
        "body": {
            "type": "BlockStatement",
            "body": [
                {
                    "type": "ReturnStatement",
                    "argument": objectExpression
                }
            ]
        },
        "rest": null,
        "generator": false,
        "expression": false
    };
}